INSERT INTO repo_cf_values (cf_value_id, education_level, sub_heading, text, status) VALUES ('CFV_SDG06_TER_004', 'Tertiary education', 'Social commitment and professional integrity', 'Demonstrate professional responsibility in keeping high standards of water and wastewater infrastructure, ensuring safety, reliability and environmental compliance.', 'Active'), ('CFV_SDG06_TER_005', 'Tertiary education', 'Social commitment and professional integrity', 'Actively contribute to societal transformation by applying knowledge to address water insecurity and sanitation challenges, particularly for vulnerable populations.', 'Active'), ('CFV_SDG06_TER_006', 'Tertiary education', 'Social commitment and professional integrity', 'Support governments and communities in building capacity to reduce the risks of water-related conflict and improve governance and peacebuilding.', 'Active'), ('CFV_SDG06_TER_007', 'Tertiary education', 'Equity and justice orientation', 'Cultivate a solution-minded and justice-oriented approach to managing competing water demands across agriculture, industry, domestic use and ecosystems.', 'Active'), ('CFV_SDG06_TER_008', 'Tertiary education', 'Equity and justice orientation', 'Promote awareness and advocacy on the global water crisis, and the need for equitable water governance rooted in local realities and global co-operation.', 'Active'), ('CFV_SDG06_TER_009', 'Tertiary education', 'Equity and justice orientation', 'Recognise and address inequalities in water access and exposure to water-related risks, particularly in marginalised or underserved communities. Sustainability and innovation mindset', 'Active'), ('CFV_SDG06_TER_010', 'Tertiary education', 'Equity and justice orientation', 'Embrace a sustainability ethos that prioritises innovation in water efficiency, circular economy practices and ecosystem restoration.', 'Active'), ('CFV_SDG06_TER_011', 'Tertiary education', 'Equity and justice orientation', 'Show readiness to scale up sustainable solutions through creativity, entrepreneurship and the generation of decent, green jobs.', 'Active'), ('CFV_SDG06_TER_012', 'Tertiary education', 'Equity and justice orientation', 'Commit to responsible water use and effluent reduction across the personal, institutional and professional spheres.', 'Active'), ('CFV_SDG06_TER_013', 'Tertiary education', 'Systems thinking and collaboration', 'Adopt a holistic and integrated understanding of water challenges, recognising links with health, food, energy, climate, economy and peace.', 'Active'), ('CFV_SDG06_TER_014', 'Tertiary education', 'Systems thinking and collaboration', 'Promote interdisciplinary and transdisciplinary collaboration, recognising that effective water solutions emerge from co-operation across science, policy and community practice.', 'Active'), ('CFV_SDG06_TER_015', 'Tertiary education', 'Systems thinking and collaboration', 'Engage in responsible decision-making that balances scientific evidence, ethical considerations and socio-political realities in water-related issues.', 'Active'), ('CFV_SDG06_TER_016', 'Tertiary education', 'Leadership and advocacy', 'Develop as ethical leaders and advocates for water justice, conservation and sustainable development at the local, national and global levels.', 'Active'), ('CFV_SDG06_TER_017', 'Tertiary education', 'Leadership and advocacy', 'Actively participate in shaping policy and planning processes that prioritise sustainable and inclusive water and sanitation infrastructure.', 'Active'), ('CFV_SDG06_TER_018', 'Tertiary education', 'Leadership and advocacy', 'Promote community engagement and behaviour change, using knowledge and tools to shift public attitudes and support sustainable water practices.', 'Active'), ('CFV_SDG06_ADULT_001', 'Adult education', 'Environmental stewardship and sustainability', 'Appreciate the intrinsic value of water and cultivate a deep respect for the health of watersheds and local water bodies.', 'Active'), ('CFV_SDG06_ADULT_002', 'Adult education', 'Environmental stewardship and sustainability', 'Express a sense of responsibility and stewardship towards protecting clean water sources and improving sanitation facilities.', 'Active'), ('CFV_SDG06_ADULT_003', 'Adult education', 'Environmental stewardship and sustainability', 'Encourage self-reflection on individual and collective roles in water usage, conservation and the promotion of sustainable practices.', 'Active'), ('CFV_SDG06_ADULT_004', 'Adult education', 'Environmental stewardship and sustainability', 'Promote values of environmental care, ensuring water and soil practices contribute to ecological balance and resilience.', 'Active'), ('CFV_SDG06_ADULT_005', 'Adult education', 'Community engagement and collective action', 'Support active community participation in managing water sustainably, recognising the importance of local co-operation and shared responsibility.', 'Active'), ('CFV_SDG06_ADULT_006', 'Adult education', 'Community engagement and collective action', 'Cultivate a community-oriented mindset and collective action to conserve water, maintain hygiene standards and manage shared resources.', 'Active'), ('CFV_SDG06_ADULT_007', 'Adult education', 'Community engagement and collective action', 'Encourage conflict resolution skills around shared water sources, encouraging co-operation, mutual respect and shared benefit.', 'Active'), ('CFV_SDG06_ADULT_008', 'Adult education', 'Community engagement and collective action', 'Promote resilience-building attitudes, particularly in communities vulnerable to climate change, by valuing long-term water security.', 'Active'), ('CFV_SDG06_ADULT_009', 'Adult education', 'Community engagement and collective action', 'Support community-based innovations that link water sustainability with economic empowerment and environmental stewardship.', 'Active'), ('CFV_SDG06_ADULT_010', 'Adult education', 'Equity, inclusion and social justice', 'Promote the principle of water as a human right, ensuring inclusive access to clean water and sanitation for all, especially vulnerable populations.', 'Active'), ('CFV_SDG06_ADULT_011', 'Adult education', 'Equity, inclusion and social justice', 'Value the role of women, indigenous peoples and tribal communities in water management and decision-making.', 'Active'), ('CFV_SDG06_ADULT_012', 'Adult education', 'Equity, inclusion and social justice', 'Support social equity by advocating for fair access, encouraging participation, and reducing disparities in water availability and quality.', 'Active'), ('CFV_SDG06_ADULT_013', 'Adult education', 'Equity, inclusion and social justice', 'Strengthen civil society engagement, embracing transparency, accountability and inclusive governance through community oversight and digital tools.', 'Active'), ('CFV_SDG06_ADULT_014', 'Adult education', 'Cultural wisdom and local knowledge', 'Leverage and respect local knowledge and traditional ecological practices in water conservation and management.', 'Active'), ('CFV_SDG06_ADULT_015', 'Adult education', 'Cultural wisdom and local knowledge', 'Value and honour indigenous approaches to water, recognising their contributions to sustainable and culturally rooted water stewardship.', 'Active'), ('CFV_SDG06_ADULT_016', 'Adult education', 'Cultural wisdom and local knowledge', 'Encourage innovation and resourcefulness, especially in using local, affordable materials for developing water and sanitation infrastructure.', 'Active'), ('CFV_SDG06_ADULT_017', 'Adult education', 'Health, hygiene and human dignity', 'Promote a strong ethic of care for public health, grounded in the importance of clean water and sanitation for disease prevention and wellbeing.', 'Active'), ('CFV_SDG06_ADULT_018', 'Adult education', 'Health, hygiene and human dignity', 'Encourage an initiative-taking attitude in supporting hygiene awareness, household water treatment and behavioural change across communities.', 'Active'), ('CFV_SDG06_ADULT_019', 'Adult education', 'Health, hygiene and human dignity', 'Instil a sense of mutual support, where communities collaborate and uplift one another in efforts to manage water effectively and equitably.', 'Active'), ('CFV_SDG07_SEC_001', 'Secondary education', 'Responsibility and environmental stewardship', 'Acknowledge the human role in climate change and commit to personal accountability in energy use.', 'Active'), ('CFV_SDG07_SEC_002', 'Secondary education', 'Responsibility and environmental stewardship', 'Promote conscious decision-making that reduces reliance on non-renewable energy sources.', 'Active'), ('CFV_SDG07_SEC_003', 'Secondary education', 'Equity and empathy', 'Develop empathy toward communities without reliable energy access.', 'Active'), ('CFV_SDG07_SEC_004', 'Secondary education', 'Equity and empathy', 'Advocate for universal access to clean, safe and affordable energy.', 'Active'), ('CFV_SDG07_SEC_005', 'Secondary education', 'Ethical awareness', 'Reflect on implications of energy systems – in terms of environmental degradation and their impacts on marginalised groups and future generations.', 'Active'), ('CFV_SDG07_SEC_006', 'Secondary education', 'Ethical awareness', 'Embrace energy justice as a core component of sustainable development.', 'Active'), ('CFV_SDG07_SEC_007', 'Secondary education', 'Commitment to action', 'Personal pledges to reduce electricity use, travel emissions and unnecessary consumption.', 'Active'), ('CFV_SDG07_SEC_008', 'Secondary education', 'Commitment to action', 'Inspire others through school-based campaigns or digital media projects on clean energy awareness.', 'Active'), ('CFV_SDG07_SEC_009', 'Secondary education', 'Curiosity and innovation', 'Stay open to exploring innovative technologies and creative solutions to energy challenges.', 'Active'), ('CFV_SDG07_SEC_010', 'Secondary education', 'Curiosity and innovation', 'Value learning from local and indigenous knowledge systems in promoting sustainable energy use.', 'Active'), ('CFV_SDG07_SEC_011', 'Secondary education', 'Collaboration and leadership', 'Promote teamwork and shared responsibility in energy-saving initiatives.', 'Active'), ('CFV_SDG07_SEC_012', 'Secondary education', 'Collaboration and leadership', 'Take leadership roles in educating others and modelling energy-conscious behaviours.', 'Active'), ('CFV_SDG07_TVET_001', 'TVET', 'Professional ethics and accountability', 'Embrace ethical responsibility in energy production and consumption, with accountability for environmental, health and social impacts.', 'Active'), ('CFV_SDG07_TVET_002', 'TVET', 'Professional ethics and accountability', 'Recognise the long-term consequences of technical decisions and prioritise sustainability in professional practice.', 'Active'), ('CFV_SDG07_TVET_003', 'TVET', 'Commitment to sustainability', 'Value renewable energy as a key driver for sustainable development and climate resilience.', 'Active'), ('CFV_SDG07_TVET_004', 'TVET', 'Commitment to sustainability', 'Support environmentally responsible practices in both work environments and communities.', 'Active') ON CONFLICT DO NOTHING;